# V8 integration mode: when non-None, FIX11/D50 consume copied RAW frames from
# the V22 UI camera owner.  The provider is duck-typed to RawPreviewController
# and MUST NOT own/open/release a physical VideoCapture.
_INTEGRATION_EXTERNAL_PREVIEW = None
_INTEGRATION_REUSE_EMPTY_BOARD_STATE = None
_INTEGRATION_ARM2_SERIAL_EXPORT = None  # opt-in V22 main-only, never enabled in standalone mode
_INTEGRATION_STOP_EVENT = None  # V10: V22 workflow cooperative-stop event; standalone remains None


def _integration_stop_requested() -> bool:
    """Return True only when V22 integration explicitly requested a cooperative stop."""
    event = _INTEGRATION_STOP_EVENT
    if event is None:
        return False
    try:
        return bool(event.is_set())
    except Exception:
        return False


def _integration_reset_registry(external_preview: Any) -> None:
    """Reset one transfer episode without touching the external V22 camera."""
    with REGISTRY.lock:
        REGISTRY.fix11_complete = False
        REGISTRY.fix11_preview = external_preview
        REGISTRY.fix11_serial_by_port.clear()
        REGISTRY.fix11_args = None
        REGISTRY.fix11_complete_at = 0.0
        REGISTRY.runtime_empty_board_bgr = None
        REGISTRY.runtime_empty_board_seq = -1
        REGISTRY.runtime_empty_board_at = 0.0
        REGISTRY.final_camera_locked = False
        REGISTRY.final_camera_lock_at = 0.0
        REGISTRY.prewarmed_seg_model = None
        REGISTRY.prewarmed_seg_model_path = None
        REGISTRY.prewarmed_pose_model = None
        REGISTRY.prewarmed_pose_model_path = None
        REGISTRY.prewarm_complete = False
        REGISTRY.prewarmed_depth_runtime = None
        REGISTRY.prewarmed_depth_error = None


def _integration_release_inference_resources() -> None:
    """Release transfer-only neural runtimes before V22 classification starts."""
    with REGISTRY.lock:
        REGISTRY.prewarmed_seg_model = None
        REGISTRY.prewarmed_seg_model_path = None
        REGISTRY.prewarmed_pose_model = None
        REGISTRY.prewarmed_pose_model_path = None
        REGISTRY.prewarmed_depth_runtime = None
        REGISTRY.prewarmed_depth_error = None
        REGISTRY.prewarm_complete = False
        REGISTRY.runtime_empty_board_bgr = None
        REGISTRY.fix11_preview = None
    try:
        import gc
        gc.collect()
    except Exception:
        pass
    try:
        import torch
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass
    builtins.print(
        "[GARMENT-TRANSFER-V9-INTEGRATION-CLEANUP] transfer inference resources released; "
        "V22 camera ownership unchanged"
    )


def run_integrated(external_preview: Any, argv: Sequence[str], *,
    on_final_empty_board: Optional[Any] = None,
    reuse_empty_board_state: Optional[Any] = None,
    on_arm2_serial_handoff: Optional[Any] = None,
    stop_event: Optional[Any] = None,
) -> int:
    """Run transfer inside the V22 process using V22's sole camera owner.

    `external_preview` must provide the RawPreviewController-compatible copied-
    frame interface.  This function never asks the provider to close the camera.

    V10 integration stop contract:
      * `stop_event` is owned by V22 main and is never cleared here.
      * physical robot commands are not hard-killed mid-segment;
      * FIX11 checks the event at verified/settled motion boundaries and then
        reuses its existing Ctrl+C safe-return path;
      * D50 sees the same event as a synthetic Q and exits cleanly;
      * rc=130 means user-requested cooperative stop, not a transfer failure.
    """
    global _INTEGRATION_EXTERNAL_PREVIEW, _INTEGRATION_REUSE_EMPTY_BOARD_STATE
    global _INTEGRATION_ARM2_SERIAL_EXPORT, _INTEGRATION_STOP_EVENT
    if external_preview is None:
        raise MergeRuntimeError("GARMENT_TRANSFER V10 integrated run requires external preview")
    if stop_event is not None and not callable(getattr(stop_event, "is_set", None)):
        raise TypeError("stop_event must provide is_set() or be None")
    old_argv = list(sys.argv)
    old_preview = _INTEGRATION_EXTERNAL_PREVIEW
    old_reuse = _INTEGRATION_REUSE_EMPTY_BOARD_STATE
    old_export = _INTEGRATION_ARM2_SERIAL_EXPORT
    old_stop_event = globals().get("_INTEGRATION_STOP_EVENT", None)
    if on_arm2_serial_handoff is not None and not callable(on_arm2_serial_handoff):
        raise TypeError("on_arm2_serial_handoff must be callable or None")
    _INTEGRATION_EXTERNAL_PREVIEW = external_preview
    _INTEGRATION_REUSE_EMPTY_BOARD_STATE = reuse_empty_board_state
    _INTEGRATION_ARM2_SERIAL_EXPORT = on_arm2_serial_handoff
    _INTEGRATION_STOP_EVENT = stop_event
    _integration_reset_registry(external_preview)
    sys.argv = [str(Path(__file__).resolve())] + list(argv)

    def _stop_requested_local() -> bool:
        callback = globals().get("_integration_stop_requested")
        if callable(callback):
            try:
                return bool(callback())
            except Exception:
                pass
        event = globals().get("_INTEGRATION_STOP_EVENT")
        try:
            return bool(event is not None and event.is_set())
        except Exception:
            return False

    try:
        if _stop_requested_local():
            builtins.print("[GARMENT-TRANSFER-V10-STOP] stop already requested before transfer startup")
            return 130
        builtins.print(
            "[GARMENT-TRANSFER-V10-SHARED-CAMERA] V22 owns /dev/video0; "
            "FIX11/D50 receive RAW copied frames only; cooperative stop connected"
        )
        try:
            result = int(main())
        except KeyboardInterrupt:
            if _stop_requested_local():
                builtins.print(
                    "[GARMENT-TRANSFER-V10-STOPPED] integration stop reached a safe FIX11 boundary; "
                    "existing safe-return/cleanup completed"
                )
                return 130
            raise
        if _stop_requested_local():
            builtins.print(
                "[GARMENT-TRANSFER-V10-STOPPED] stop observed after transfer phase return; "
                "BOARD_READY handoff suppressed"
            )
            return 130
        if result == 0:
            # REGISTRY holds the actual FIX46 image captured BEFORE the first
            # basket motion, not a new image of the occupied board.
            with REGISTRY.lock:
                if not REGISTRY.final_camera_locked or REGISTRY.runtime_empty_board_bgr is None:
                    raise MergeRuntimeError("FIX46 final camera baseline unavailable at BOARD_READY")
                frame = np.asarray(REGISTRY.runtime_empty_board_bgr, np.uint8).copy()
                seq = int(REGISTRY.runtime_empty_board_seq)
                captured_at = float(REGISTRY.runtime_empty_board_at)
            if not callable(on_final_empty_board):
                raise MergeRuntimeError("integrated transfer requires final baseline handoff callback")
            on_final_empty_board(frame, seq, captured_at)
            builtins.print(
                f"[GARMENT-TRANSFER-MAIN-BASELINE-HANDOFF] seq={seq} "
                "same pre-basket FIX46 reference"
            )
        return result
    finally:
        sys.argv = old_argv
        _INTEGRATION_EXTERNAL_PREVIEW = old_preview
        _INTEGRATION_REUSE_EMPTY_BOARD_STATE = old_reuse
        _INTEGRATION_ARM2_SERIAL_EXPORT = old_export
        _INTEGRATION_STOP_EVENT = old_stop_event
        _integration_release_inference_resources()
