                    times = [entry[0] for entry in stable_samples]
                    samples = np.asarray([entry[1] for entry in stable_samples], dtype=np.float64)
                    median_pose = np.median(samples, axis=0)
                    offsets = np.linalg.norm(samples - median_pose[None, :], axis=1)
                    pose_span = float(np.max(offsets)) if offsets.size else float("inf")
                    z_span = float(np.max(samples[:, 2]) - np.min(samples[:, 2]))
                    duration = float(times[-1] - times[0])
                    stable = duration >= 0.40 and pose_span <= 2.5 and z_span <= 1.5

