                            local_axis = max(abs(float(median_pose[0])), abs(float(median_pose[1])))
                            radius_limit = max(50.0, float(args.laydown_roarm_radius_max_mm))
                            axis_limit = max(50.0, float(args.laydown_local_axis_max_mm))
                            local_reach_safe = bool(local_radius <= radius_limit + 1e-6 and local_axis <= axis_limit + 1e-6)
                            xy_error = float(np.linalg.norm(median_pose[:2] - target[:2]))
                            xy_limit = max(15.0, float(args.move_tolerance_mm))
                            target_shortfall = float(target[2] - median_pose[2])
                            max_shortfall = max(35.0, float(args.move_tolerance_mm) + 10.0)
                            below_or_at_target = bool(float(median_pose[2]) <= float(target[2]) + 2.0)
                            bounded_shortfall = bool(target_shortfall <= max_shortfall)
                            total_error = float(np.linalg.norm(median_pose - target))
                            total_error_limit = max(40.0, float(args.move_tolerance_mm) + 15.0)
                            close_enough_3d = bool(total_error <= total_error_limit)

