    # FIX111: teammate D31 labels say APPROACH_OPEN / CONTACT_OPEN, but its
    # original _d31_move_verified() always sent cfg.tool_t_rad (~3.14) in T:104.
    # On this RoArm stack T:104 `t` and T:106 both influence the hand/tool state;
    # therefore an OPEN T:106 could be contradicted by the immediately following
    # Cartesian T:104.  Keep T:104 `t` explicitly OPEN for those two stages and
    # use T:106 close only after contact is complete.
    _fix111_d31_wait = _fix103_team_ns["_d31_conservative_wait_seconds"]
    _fix111_d31_query = _fix103_team_ns["_d31_query_feedback"]

    def _fix111_d31_move_verified(arm, target_xyz, cfg, speed, move_command, args, label,
                                  wait_from=None, tolerance_mm=None):
        target = np.asarray(target_xyz, dtype=np.float32)
        label_s = str(label)
        label_u = label_s.upper()
        is_open_cartesian = (
            "WAISTTOP_APPROACH_OPEN" in label_u
            or "WAISTTOP_CONTACT_OPEN" in label_u
        )
        move_t = float(getattr(args, "d31_grip_open", 1.35)) if is_open_cartesian else float(cfg.tool_t_rad)
        mode = "OPEN_LOCK" if is_open_cartesian else "CFG_TOOL_T"
        print(
            f"[D31-{label_s}] {arm.label} target=({target[0]:.1f},{target[1]:.1f},{target[2]:.1f}) "
            f"speed={float(speed):.2f}"
        )
        if is_open_cartesian:
            print(
                f"[FIX111-T104-OPEN-LOCK] {arm.label} stage={label_s} "
                f"T:104 t={move_t:.3f}; cfg.tool_t={float(cfg.tool_t_rad):.3f} is intentionally NOT used"
            )
        try:
            print(
                f"[D31-CMD {time.monotonic():.6f}] {arm.label} T:{int(move_command)} stage={label_s} "
                f"x={float(target[0]):.2f} y={float(target[1]):.2f} z={float(target[2]):.2f} "
                f"tool_t={move_t:.3f} spd={float(speed):.3f} mode={mode}"
            )
            arm.move_goal(
                float(target[0]), float(target[1]), float(target[2]), move_t, float(speed),
                move_command=move_command, stage=label_s, caller='FIX111_d31_move_verified'
            )
            if wait_from is None:
                wait_s = max(
                    float(getattr(args, 'd31_min_stage_wait_s', 1.2)),
                    float(getattr(args, 'd31_unknown_start_wait_s', 3.0)),
                )
            else:
                wait_s = _fix111_d31_wait(
                    np.asarray(wait_from, dtype=np.float32), target, float(speed), args,
                    extra=float(getattr(args, 'd31_motion_extra_wait_s', 0.55)),
                )
            time.sleep(wait_s)
            print(f"[D31-{label_s}] {arm.label} arrival barrier completed after wait={wait_s:.2f}s")

            # At the two OPEN stages, obtain a fresh state sample.  If the hand is
            # clearly still in a closed-like state, re-assert OPEN at the reached
            # XYZ before the later close command. Missing feedback alone is not a
            # new block; explicit closed-like feedback is repaired first.
            if is_open_cartesian:
                fb = _fix111_d31_query(arm, timeout_s=1.10)
                hand_t = None
                if isinstance(fb, dict):
                    try:
                        hand_t = float(fb.get('t'))
                    except Exception:
                        hand_t = None
                print(
                    f"[FIX111-OPEN-STAGE-FEEDBACK] {arm.label} stage={label_s} "
                    f"targetOpen={move_t:.3f} actualT={(f'{hand_t:.3f}' if hand_t is not None else 'NA')}"
                )
                if hand_t is not None and hand_t > 2.15:
                    print(
                        f"[FIX111-OPEN-REASSERT] {arm.label} stage={label_s} "
                        f"actualT={hand_t:.3f} is closed-like; sending T:106 OPEN={move_t:.3f} twice at fixed XYZ"
                    )
                    for rep in range(2):
                        arm.set_gripper(
                            move_t, delay=0.22, stage=label_s,
                            caller=f'FIX111_OPEN_REASSERT_{rep+1}'
                        )
                        if rep == 0:
                            time.sleep(0.10)
                    time.sleep(0.15)
                    fb2 = _fix111_d31_query(arm, timeout_s=1.10)
                    hand2 = None
                    if isinstance(fb2, dict):
                        try:
                            hand2 = float(fb2.get('t'))
                        except Exception:
                            hand2 = None
                    print(
                        f"[FIX111-OPEN-REASSERT-RESULT] {arm.label} stage={label_s} "
                        f"actualT={(f'{hand2:.3f}' if hand2 is not None else 'NA')}"
                    )
                    if hand2 is not None and hand2 > 2.15:
                        return (
                            False,
                            f"FIX111_{label_s}_HAND_NOT_OPEN_AFTER_REASSERT:{hand2:.3f}",
                            fb2,
                        )
            return (True, 'OK', None)
        except Exception as exc:
            print(f"[D31-{label_s}-ERROR] {arm.label}: {exc!r}")
            return (False, f"{label_s}_COMMAND_FAILED:{exc!r}", None)

    _fix103_team_ns["_d31_move_verified"] = _fix111_d31_move_verified
    print(
        "[FIX111-SECOND-GRASP-STATE-PATCH-READY] "
        "WAISTTOP APPROACH_OPEN/CONTACT_OPEN T:104 now carry OPEN t; "
        "B31 close uses ARM1-first stagger + torque/redundant T:106 + feedback latch"
    )

    def _fix104_fast_edge_reframe_geometry(source, config, cfg, args):
        """FIX104 bounded fast-first form of teammate V11 reframe search.

        Same geometry and same path-reach / pair-clearance checks as V11, but
        returns the FIRST valid candidate at the deepest available edge instead
        of exhaustively scoring every valid candidate.  Candidate order is
        interleaved around source-mid and board-center so a useful centered route
        is not delayed behind thousands of equivalent source-mid offsets.
        """
        q2 = np.asarray(source["arm2"], np.float32).reshape(2)
        q1 = np.asarray(source["arm1"], np.float32).reshape(2)
        if not (np.all(np.isfinite(q2)) and np.all(np.isfinite(q1))):
            return None, "TSHIRT_V11_NONFINITE_SOURCE"
        if float(q2[0]) >= float(q1[0]):
            return None, "TSHIRT_V11_SOURCE_X_ORDER_INVALID"
        src_vec=(q1-q2).astype(np.float32)
        src_width=float(np.linalg.norm(src_vec)); src_xsep=float(q1[0]-q2[0])
        src_angle=float(__import__("math").degrees(__import__("math").atan2(float(src_vec[1]),float(src_vec[0]))))
        src_mid=0.5*(q2+q1)
        min_pair_sep=float(np.clip(getattr(args,"tshirt_v11_min_pair_sep_mm",75.0),55.0,130.0))
        if src_width < min_pair_sep:
            return None, f"TSHIRT_V11_SOURCE_PAIR_TOO_CLOSE_{src_width:.1f}<{min_pair_sep:.1f}"
        board_bottom=float(min(cfg.board_y_min,cfg.board_y_max)); board_top=float(max(cfg.board_y_min,cfg.board_y_max))
        board_mid_x=float(getattr(cfg,"split_board_x",0.5*(float(cfg.board_x_min)+float(cfg.board_x_max))))
        max_y=float(np.clip(getattr(args,"tshirt_v11_max_common_y_shift_mm",30.0),0.0,50.0))
        ystep=float(np.clip(getattr(args,"tshirt_v11_launch_y_step_mm",10.0),5.0,20.0))
        desired_edge=float(np.clip(getattr(args,"tshirt_v11_edge_inset_mm",20.0),10.0,45.0))
        max_edge=float(np.clip(getattr(args,"tshirt_v11_max_edge_inset_mm",70.0),desired_edge,100.0))
        estep=float(np.clip(getattr(args,"tshirt_v11_edge_inset_step_mm",5.0),2.0,15.0))
        max_width=float(np.clip(getattr(args,"tshirt_v11_max_launch_width_mm",390.0),300.0,440.0))
        max_spread=float(np.clip(getattr(args,"tshirt_v11_max_extra_spread_mm",135.0),40.0,180.0))
        wstep=float(np.clip(getattr(args,"tshirt_v11_width_step_mm",10.0),5.0,20.0))
        max_cx=float(np.clip(getattr(args,"tshirt_v11_center_x_search_mm",90.0),30.0,140.0))
        cxstep=float(np.clip(getattr(args,"tshirt_v11_center_x_step_mm",8.0),4.0,20.0))
        xmargin=float(np.clip(getattr(args,"tshirt_v11_board_x_margin_mm",10.0),5.0,25.0))
        ymargin=float(np.clip(getattr(args,"tshirt_v11_launch_board_y_margin_mm",20.0),8.0,50.0))
        # 9 samples keeps the same continuous-path guard while avoiding the prior
        # 13x multiplier in an exhaustive combinatorial search.
        path_samples=int(np.clip(getattr(args,"tshirt_v11_path_samples",13),7,21))
        path_samples=min(path_samples,9)

        def offs(limit, step):
            vals=[0.0]; n=int(__import__("math").floor(limit/step+1e-9))
            for i in range(1,n+1):
                d=float(i*step); vals.extend([d,-d])
            return vals
        # Interleave source-mid and board-center at each offset magnitude.
        centers=[]
        for d in offs(max_cx,cxstep):
            for base in (float(src_mid[0]),board_mid_x):
                v=float(base+d)
                if not any(abs(v-old)<1e-4 for old in centers): centers.append(v)
        launch_ys=[float(src_mid[1]+d) for d in offs(max_y,ystep)]
        width0=max(src_width,src_xsep); width_max=min(max_width,width0+max_spread)
        widths=[]; w=float(width0)
        while w<=width_max+1e-6:
            widths.append(w); w+=wstep
        if not widths or widths[-1] < width_max-2.0: widths.append(width_max)
        edge_insets=[]; e=float(desired_edge)
        while e<=max_edge+1e-6:
            edge_insets.append(e); e+=estep
        path_ok=_fix103_team_ns["_tshirt_v10_path_reach_ok"]
        reject={}; tested=0; started=time.monotonic()
        for edge_inset in edge_insets:
            edge_y=float(board_bottom+edge_inset)
            builtins.print(f"[FIX104-REFRAME-SEARCH] edgeInset={edge_inset:.1f}mm tested={tested}")
            for launch_y in launch_ys:
                if not (board_bottom+ymargin < launch_y < board_top-ymargin):
                    continue
                for width in widths:
                    half=0.5*float(width)
                    for cx in centers:
                        tested += 1
                        launch={"arm2":np.asarray([cx-half,launch_y],np.float32),"arm1":np.asarray([cx+half,launch_y],np.float32)}
                        edge={"arm2":np.asarray([cx-half,edge_y],np.float32),"arm1":np.asarray([cx+half,edge_y],np.float32)}
                        if not (float(cfg.board_x_min)+xmargin <= float(launch["arm2"][0]) and float(launch["arm1"][0]) <= float(cfg.board_x_max)-xmargin):
                            reject["BOARD_X"]=reject.get("BOARD_X",0)+1; continue
                        desired_mid=np.asarray([cx,launch_y],np.float32); delta=(desired_mid-src_mid).astype(np.float32)
                        translated={"arm2":(q2+delta).astype(np.float32),"arm1":(q1+delta).astype(np.float32)}
                        if abs(float(delta[1])) > max_y+1e-5:
                            reject["COMMON_Y_SHIFT"]=reject.get("COMMON_Y_SHIFT",0)+1; continue
                        stage_ok=True; radius_sum=0.0
                        for k,srcp in (("arm2",q2),("arm1",q1)):
                            for tag,a,b,final in (("TRANSLATE",srcp,translated[k],False),("LEVEL_SPREAD",translated[k],launch[k],False),("EDGE",launch[k],edge[k],True)):
                                ok,why,r=path_ok(config,k,a,b,args,samples=path_samples,final_target=final)
                                if not ok:
                                    key=f"{tag}_{k}_{str(why).split(':',1)[0]}"; reject[key]=reject.get(key,0)+1; stage_ok=False; break
                                radius_sum += float(r)
                            if not stage_ok: break
                        if not stage_ok: continue
                        min_sep=float("inf"); min_xsep=float("inf")
                        for tt in np.linspace(0.0,1.0,path_samples):
                            a2=((1.0-float(tt))*translated["arm2"]+float(tt)*launch["arm2"]).astype(np.float32)
                            a1=((1.0-float(tt))*translated["arm1"]+float(tt)*launch["arm1"]).astype(np.float32)
                            min_sep=min(min_sep,float(np.linalg.norm(a1-a2))); min_xsep=min(min_xsep,float(a1[0]-a2[0]))
                        if min_sep < min_pair_sep or min_xsep < 45.0:
                            reject["PAIR_CLEARANCE"]=reject.get("PAIR_CLEARANCE",0)+1; continue
                        common_dy=float(edge_y-launch_y)
                        if common_dy >= -40.0:
                            reject["EDGE_DROP_TOO_SHORT"]=reject.get("EDGE_DROP_TOO_SHORT",0)+1; continue
                        spread_extra=float(width-src_width)
                        cand={
                            "translate":translated,"launch":launch,"edge":edge,
                            "source_angle_deg":src_angle,"source_width_mm":src_width,"launch_width_mm":float(width),
                            "extra_spread_mm":spread_extra,"source_mid_board":src_mid.copy(),"launch_mid_board":desired_mid,
                            "common_translation_board":delta,"launch_y_mm":float(launch_y),"edge_y_mm":float(edge_y),
                            "edge_inset_mm":float(edge_inset),"common_drop_mm":abs(common_dy),"common_dy_mm":common_dy,
                            "min_reframe_pair_sep_mm":min_sep,"min_reframe_x_sep_mm":min_xsep,"score":0.0,
                        }
                        builtins.print(
                            f"[FIX104-REFRAME-FAST-READY] tested={tested} elapsed={time.monotonic()-started:.2f}s "
                            f"edgeInset={edge_inset:.1f} launchY={launch_y:.1f} width={src_width:.1f}->{width:.1f} "
                            f"centerX={cx:.1f} equalDY={common_dy:.1f}"
                        )
                        builtins.print(
                            f"[TSHIRT-V11-EDGE-STAGE-PLAN] sourceMid={np.round(src_mid,1).tolist()} "
                            f"commonMove={np.round(delta,1).tolist()} launchMid={np.round(desired_mid,1).tolist()} "
                            f"launchY={launch_y:.1f} width={src_width:.1f}->{width:.1f} edgeY={edge_y:.1f} "
                            f"inset={edge_inset:.1f} EQUAL_DY={common_dy:.1f}"
                        )
                        return cand,"OK"
                        
                        # intentionally first-valid at deepest edge
            # continue to a shallower edge only if no candidate exists here
        builtins.print(
            f"[FIX104-REFRAME-PLAN-BLOCK] tested={tested} elapsed={time.monotonic()-started:.2f}s rejects={reject}"
        )
        return None,"TSHIRT_V11_NO_REACHABLE_EQUAL_EDGE_ROUTE"

    # `_tshirt_v1_build_edge_plan` resolves this symbol from its isolated globals
    # at call time, so this safely replaces only the expensive V11 search.
    _fix103_team_ns["_tshirt_v11_edge_reframe_geometry"] = _fix104_fast_edge_reframe_geometry
    builtins.print(
        "[FIX104-REFRAME-PATCH-READY] teammate SAME-Y/EDGE geometry preserved; "
        "exhaustive best-score search replaced by deepest-edge first-valid search"
    )

    _fix103_required_helpers = (
        "_tshirt_v1_build_edge_plan",
        "_step120_v9_execute_edge_comb",
        "_tshirt_v13_waist78_source_pair",
        "_tshirt_v11_edge_reframe_geometry",
        "_tshirt_v14_build_two_stage_edge_flick",
        "_tshirt_v17_build_extended_return_pullup",
    )
    _fix103_missing_helpers = [
        _name for _name in _fix103_required_helpers
        if not callable(_fix103_team_ns.get(_name))
    ]
    if _fix103_missing_helpers:
        raise MergeRuntimeError(
            "FIX103 teammate helper transplant incomplete: "
            + ", ".join(_fix103_missing_helpers)
        )
    builtins.print(
        "[FIX104-TEAMMATE-HELPERS-READY] isolated WAIST78/REFRAME/SAME-Y/"
        "EDGE-DROP/FLICK/GRAVITY/PULLBACK executor loaded; teammate camera/serial/main excluded"
    )

    class _Fix103Args:
        def __init__(self):
            for _key, _value in FIX103_TEAMMATE_ARGS_DEFAULTS.items():
                setattr(self, _key, copy.deepcopy(_value))
            # Mode 2 is authoritative, but there is no keyboard state in FIX103.
            self.tshirt_active_grasp_mode = "waist78"
            self.tshirt_grasp_mode = "waist78"
            self.send = True
            self.dry_run = False
            self.hover_only = False
            self.enter_confirm = False
            self.move_command = 104

    def _fix103_pose_state_to_teammate(pose_state, H_value):
        """Convert FIX102's already-computed 12-point pose to teammate pose_info."""
        if not isinstance(pose_state, dict):
            raise RuntimeError("FIX103 pose state is unavailable")
        H_arr = np.asarray(H_value, dtype=np.float32).reshape(3, 3)
        board = {}
        px = {}
        conf = {}
        points = list(pose_state.get("points", []) or [])
        for item in points:
            try:
                idx = int(item.get("index"))
                if idx < 0 or idx >= len(FIX17_TSHIRT_POSE_KPT_NAMES):
                    continue
                name = str(FIX17_TSHIRT_POSE_KPT_NAMES[idx])
                x = float(item.get("x"))
                y = float(item.get("y"))
                c = float(item.get("conf", 0.0))
                bx, by = module.pixel_to_board(H_arr, x, y)
            except Exception:
                continue
            px[name] = [x, y]
            board[name] = [float(bx), float(by)]
            conf[name] = c

        missing = [
            name for name in ("waist_right", "waist_left")
            if name not in board
        ]
        if missing:
            raise RuntimeError(
                "FIX103 fresh pose missing KPT7/8 semantics: " + ",".join(missing)
            )
        # FIX102 uses one authoritative fresh frame. The teammate's original
        # 3-frame consensus spread is therefore zero by construction here; we do
        # not run a second pose model or duplicate perception.
        spreads = {name: 0.0 for name in board}
        return {
            "board": board,
            "px": px,
            "conf": conf,
            "consensus_spread_mm": spreads,
            "valid_names": list(board.keys()),
            "source": "FIX102_FRESH_MASK_FRAME_A150_POSE",
        }

    def _fix103_mask_kpt78_diag(mask_u8, pose_state):
        """Diagnostic only: mask support never becomes a millimetre-tight veto."""
        diag = {}
        if mask_u8 is None or not isinstance(pose_state, dict):
            return diag
        m = np.asarray(mask_u8)
        if m.ndim != 2 or m.size == 0:
            return diag
        h, w = m.shape[:2]
        for item in list(pose_state.get("points", []) or []):
            try:
                idx = int(item.get("index"))
                if idx not in (7, 8):
                    continue
                x = int(round(float(item.get("x"))))
                y = int(round(float(item.get("y"))))
                inside = bool(0 <= x < w and 0 <= y < h and m[y, x] > 0)
                diag[idx] = {
                    "inside_mask_pixel": inside,
                    "pixel": [x, y],
                    "conf": float(item.get("conf", 0.0)),
                }
            except Exception:
                continue
        return diag

    def _fix103_execute_second_stage(pose_state, mask_u8, H_value, config, cfg):
        """FIX103 automatic fresh-KPT7/8 WAIST78 -> EDGE-COMB gravity unfold."""
        if bool(getattr(module, "_FIX103_SECOND_STAGE_ATTEMPTED", False)):
            return bool(getattr(module, "_FIX103_SECOND_STAGE_COMPLETE", False))
        if not bool(getattr(module, "_FIX102_POST_LAYDOWN_STANDBY_READY", False)):
            builtins.print(
                "[FIX103-SECOND-STAGE-BLOCKED] FIX102 taught-standby was not physically confirmed"
            )
            return False

        module._FIX103_SECOND_STAGE_ATTEMPTED = True
        args103 = _Fix103Args()
        cfg103 = copy.copy(cfg)
        # The D50 phase deliberately advertises send=False. The transplanted
        # motion executor receives a private physical cfg copy only.
        for _key, _value in (
            ("send", True),
            ("dry_run", False),
            ("hover_only", False),
            ("enter_confirm", False),
        ):
            try:
                setattr(cfg103, _key, _value)
            except Exception:
                pass

        # FIX103 CONFIG ADAPTER -------------------------------------------------
        # Do NOT inherit the teammate script's historical 494mm-board constants.
        # The current FIX102 board/config is authoritative (current board width is
        # ~649mm in this project). Supply only fields the teammate helper expects,
        # deriving geometry/contact/standby from the LIVE current cfg.
        try:
            _bx0 = float(getattr(cfg, "board_x_min"))
            _bx1 = float(getattr(cfg, "board_x_max"))
            _by0 = float(getattr(cfg, "board_y_min"))
            _by1 = float(getattr(cfg, "board_y_max"))
        except Exception as exc:
            raise RuntimeError(f"FIX103 current board bounds unavailable: {exc!r}")
        _cfg_compat = {
            "board_margin_mm": float(getattr(cfg, "board_margin_mm", 18.0)),
            "split_board_x": 0.5 * (_bx0 + _bx1),
            "center_dead_half_width": float(getattr(cfg, "center_dead_half_width", 40.0)),
            "private_workspace_margin_mm": float(getattr(cfg, "private_workspace_margin_mm", 8.0)),
            "clear_z": float(getattr(cfg, "clear_z", 180.0)),
            "min_safe_contact_z": float(getattr(cfg, "min_safe_contact_z", -160.0)),
        }
        for _key, _value in _cfg_compat.items():
            setattr(cfg103, _key, _value)

        # Preserve current FIX102 contact calibration rather than teammate legacy
        # absolute Z defaults. V23 then adds -3mm to both; V24 adds another -2mm
        # to ARM1 contact only, exactly as the teammate V24 policy specifies.
        _a1_contact = float(module.arm_contact_z(cfg, "arm1"))
        _a2_contact = float(module.arm_contact_z(cfg, "arm2"))
        setattr(cfg103, "arm1_grip_z", _a1_contact)
        setattr(cfg103, "arm2_grip_z", _a2_contact)
        setattr(cfg103, "grip_z", 0.5 * (_a1_contact + _a2_contact))

        # Teammate recovery helpers may reference standby fields even though the
        # normal successful final standby is delegated to FIX102. Fill them from
        # the current taught standby function, never from legacy constants.
        _st1 = np.asarray(module.standby_roarm_pose(cfg, "arm1"), dtype=np.float64).reshape(-1)
        _st2 = np.asarray(module.standby_roarm_pose(cfg, "arm2"), dtype=np.float64).reshape(-1)
        for _prefix, _st in (("arm1", _st1), ("arm2", _st2)):
            setattr(cfg103, f"{_prefix}_standby_roarm_x", float(_st[0]))
            setattr(cfg103, f"{_prefix}_standby_roarm_y", float(_st[1]))
            setattr(cfg103, f"{_prefix}_standby_roarm_z", float(_st[2]))
            setattr(cfg103, f"{_prefix}_standby_roarm_t", float(_st[3]) if len(_st) > 3 else 1.57)

        builtins.print(
            f"[FIX103-CONFIG-ADAPTER] boardX=({_bx0:.1f},{_bx1:.1f}) "
            f"splitX={float(cfg103.split_board_x):.1f} | "
            f"contactZ ARM1={_a1_contact:.1f} ARM2={_a2_contact:.1f} | "
            "legacy teammate board/contact constants NOT used"
        )

        try:
            pose_info = _fix103_pose_state_to_teammate(pose_state, H_value)
        except Exception as exc:
            builtins.print(f"[FIX103-SECOND-POSE-BLOCKED] {exc!r}")
            module._FIX103_SECOND_STAGE_REPORT = {"error": repr(exc), "stage": "POSE_ADAPTER"}
            return False

        builtins.print(
            "[FIX103-SECOND-KPT78] fresh post-laydown KPT7/8 only; "
            f"KPT7={pose_info['board'].get('waist_right')} "
            f"KPT8={pose_info['board'].get('waist_left')}"
        )
        mask_diag = _fix103_mask_kpt78_diag(mask_u8, pose_state)
        builtins.print(f"[FIX103-KPT78-MASK-DIAG] diagnosticOnly=1 {mask_diag}")

        planner = _fix103_team_ns["_tshirt_v1_build_edge_plan"]
        try:
            plan = planner(pose_info, config, cfg103, args103)
        except Exception as exc:
            builtins.print(f"[FIX103-WAIST78-PLAN-ERROR] {exc!r}")
            module._FIX103_SECOND_STAGE_REPORT = {"error": repr(exc), "stage": "WAIST78_PLAN"}
            return False

        module._FIX103_SECOND_STAGE_PLAN = copy.deepcopy(plan)
        if not isinstance(plan, dict) or not bool(plan.get("ok", False)):
            reason = str((plan or {}).get("reason", "UNKNOWN_PLAN_FAILURE"))
            builtins.print(
                f"[FIX103-WAIST78-PLAN-BLOCKED] reason={reason}; no robot motion sent"
            )
            module._FIX103_SECOND_STAGE_REPORT = {
                "stage": "WAIST78_PLAN",
                "reason": reason,
                "plan": plan,
            }
            return False

        source = dict(plan.get("step120_v15_source_grips_board", {}) or {})
        translate = dict(plan.get("tshirt_v11_translate_targets_board", {}) or {})
        launch = dict(plan.get("tshirt_v11_launch_targets_board", {}) or {})
        edge = dict(plan.get("tshirt_v11_edge_targets_board", {}) or {})
        builtins.print(
            "[FIX103-WAIST78-PLAN-READY] teammate V24 geometry accepted | "
            f"source={source} | translate={translate} | SAME-Y launch={launch} | edge={edge}"
        )
        builtins.print(
            f"[FIX103-PRE-MOTION-HOLD] {float(_FIX103_PRE_MOTION_HOLD_S):.2f}s | "
            "next=vertical grasp -> pure-Z lift -> reframe -> SAME-Y -> fast EDGE drop"
        )
        time.sleep(float(_FIX103_PRE_MOTION_HOLD_S))

        args1 = REGISTRY.fix11_args
        arm1_port = str(getattr(args1, "arm1_port", "/dev/roarm_1"))
        arm2_port = str(getattr(args1, "arm2_port", "/dev/roarm_2"))
        with REGISTRY.lock:
            raw_arms = {
                "arm1": REGISTRY.fix11_serial_by_port.get(arm1_port),
                "arm2": REGISTRY.fix11_serial_by_port.get(arm2_port),
            }
        if raw_arms["arm1"] is None or raw_arms["arm2"] is None:
            builtins.print("[FIX103-SECOND-STAGE-BLOCKED] persistent ARM1/ARM2 session missing; USB reopen forbidden")
            return False
        arms103 = {
            "arm1": D50SerialAdapter(raw_arms["arm1"], arm1_port, "ARM1"),
            "arm2": D50SerialAdapter(raw_arms["arm2"], arm2_port, "ARM2"),
        }

        builtins.print(
            "[FIX103-GRAVITY-UNFOLD-START] AUTO: WAIST78 grasp -> +18mm -> +8mm -> "
            "small common translate -> rotate/spread -> SAME-Y launch -> long edge stroke -> "
            "fast flick -> gravity settle -> CLOSED pull-back"
        )
        executor = _fix103_team_ns["_step120_v9_execute_edge_comb"]
        try:
            ok_exec, why_exec, report = executor(
                plan, arms103, config, cfg103, args103
            )
        except Exception as exc:
            ok_exec, why_exec, report = False, f"EXEC_EXCEPTION:{exc!r}", {"exception": repr(exc)}
        module._FIX103_SECOND_STAGE_REPORT = copy.deepcopy(report)

        # The teammate executor is transplanted with its own final standby
        # deliberately disabled. It still owns anti-drop, return verification,
        # final lower/release, and pure-Z clear. FIX102 owns the final standby.
        released_or_postrelease = bool(
            isinstance(report, dict)
            and (
                bool(report.get("released", False))
                or "post_release_vertical_clear" in report
                or str(why_exec).startswith("POST_RELEASE")
                or str(why_exec).startswith("ACTION_OK")
            )
        )

        standby_ok = False
        if released_or_postrelease:
            final_hint = {}
            for k in ("arm1", "arm2"):
                got = _fix81_feedback(raw_arms[k], 0.9)
                if got is not None:
                    final_hint[k] = np.asarray(got[1], dtype=np.float64)
                else:
                    st = np.asarray(module.standby_roarm_pose(cfg, k), dtype=np.float64).reshape(-1)
                    final_hint[k] = st[:3].copy()
            standby_fn = getattr(module, "_FIX102_RELAXED_POST_LAYDOWN_STANDBY", None)
            if callable(standby_fn):
                try:
                    standby_ok, standby_diag = standby_fn(final_hint)
                    if isinstance(report, dict):
                        report["fix103_final_fix102_standby"] = standby_diag
                except Exception as exc:
                    standby_ok = False
                    builtins.print(f"[FIX103-FINAL-STANDBY-WARN] {exc!r}")
            else:
                builtins.print("[FIX103-FINAL-STANDBY-WARN] FIX102 standby routine unavailable")

        if ok_exec and standby_ok:
            module._FIX103_SECOND_STAGE_COMPLETE = True
            builtins.print(
                "[FIX103-GRAVITY-UNFOLD-COMPLETE] fresh KPT7/8 -> 54~42mm diagonal inward -> "
                "reframe/SAME-Y -> edge drop/flick/gravity -> CLOSED pull-back -> release -> BOTH standby COMPLETE"
            )
            return True

        if not ok_exec:
            if released_or_postrelease:
                builtins.print(
                    f"[FIX103-GRAVITY-UNFOLD-INCOMPLETE-AFTER-RELEASE] status={why_exec}; "
                    f"FIX102 standby attempted={int(standby_ok)}"
                )
            else:
                builtins.print(
                    f"[FIX103-GRAVITY-UNFOLD-HOLD] status={why_exec}; "
                    "teammate anti-drop policy remains authoritative: no forced OPEN/standby"
                )
        elif not standby_ok:
            builtins.print(
                "[FIX103-GRAVITY-UNFOLD-STANDBY-WARN] EDGE-COMB/release succeeded, "
                "but final FIX102 taught-standby was not verified"
            )
        return False

