# =============================================================================
# GARMENT TRANSFER V2: TRANSFER-ONLY D50 PATCH
# =============================================================================
# IMPORTANT:
# - _patch_d50_source remains the untouched authoritative FIX130 patch.
# - Only the physical D50 module load uses this additional transfer patch.
# - Therefore all inherited FIX85~FIX130 self-tests continue to validate the
#   original FIX130 source contract without seeing the BOARD_READY cut.
def _patch_d50_source_for_transfer(text: str) -> str:
    text = _patch_d50_source(text)

    old = '''                    if _fix113_status == "OK":
                        globals()["_FIX113_POSTPLACE_ACCEPTED"] = True
                        print("[FIX113-POSTPLACE-GATE] ACCEPTED -> existing FIX105 91mm recenter is now authorized")
'''
    new = '''                    if _fix113_status == "OK":
                        globals()["_FIX113_POSTPLACE_ACCEPTED"] = True
                        globals()["_GARMENT_TRANSFER_BOARD_READY"] = True
                        print(
                            "[GARMENT-TRANSFER-BOARD-READY] FIX113 transfer integrity ACCEPTED; "
                            "CASE1/CASE2 recovery is complete if it was needed. "
                            "STOP BEFORE FIX105 91mm recenter."
                        )
                        print(
                            f"[GARMENT-TRANSFER-BOARD-READY-DIAG] "
                            f"source={_fix76_source} area={int(_fix76_area)}px "
                            f"suspect={int(bool(_fix76_suspect))}"
                        )
                        return 0  # transfer-only integration boundary
'''
    count = text.count(old)
    if count != 1:
        raise MergeRuntimeError(
            f"GARMENT-TRANSFER-V7 board-ready gate count={count}; expected exactly 1"
        )
    return text.replace(old, new, 1)


_GARMENT_TRANSFER_V2_INHERITED_FIX130_SELF_TEST = _self_test


def _self_test(fix11_path: Path, d50_path: Path) -> int:
    base_rc = int(_GARMENT_TRANSFER_V2_INHERITED_FIX130_SELF_TEST(fix11_path, d50_path))
    if base_rc != 0:
        return base_rc

    try:
        raw_d50 = d50_path.read_text(encoding="utf-8")
        original_patched = _patch_d50_source(raw_d50)
        transfer_patched = _patch_d50_source_for_transfer(raw_d50)
        compile(
            transfer_patched,
            str(d50_path) + "<GARMENT-TRANSFER-V7-patched>",
            "exec",
        )

        original_gate = (
            "[FIX113-POSTPLACE-GATE] ACCEPTED -> existing FIX105 91mm recenter is now authorized"
        )
        ready_marker = "[GARMENT-TRANSFER-BOARD-READY]"
        recenter_marker = "[FIX105-RECENTER-TRIGGER]"

        ready_pos = transfer_patched.find(ready_marker)
        recenter_pos = (
            transfer_patched.find(recenter_marker, ready_pos + 1)
            if ready_pos >= 0
            else -1
        )
        boundary_slice = (
            transfer_patched[ready_pos:recenter_pos]
            if ready_pos >= 0 and recenter_pos > ready_pos
            else ""
        )

        own_source = Path(__file__).read_text(encoding="utf-8")

        board_ready_checks = {
            "original_gate_preserved_in_fix130": original_gate in original_patched,
            "ready_marker_absent_from_fix130": ready_marker not in original_patched,
            "original_gate_removed_in_transfer": original_gate not in transfer_patched,
            "ready_marker_exactly_once": transfer_patched.count(ready_marker) == 1,
            "ready_marker_found": ready_pos >= 0,
            "recenter_after_ready": recenter_pos > ready_pos,
            "return_before_recenter": (
                "return 0  # transfer-only integration boundary" in boundary_slice
            ),
            "board_ready_state_set": (
                'globals()["_GARMENT_TRANSFER_BOARD_READY"] = True' in transfer_patched
            ),
        }

        # CASE2 safe-floor is launcher runtime logic inside _patch_d50_module(),
        # not D50 source-text transformation. Validate it against this launcher
        # source instead of transfer_patched.
        case2_safe_checks = {
            "case2_label_guard": (
                'label == "CASE2-6-POST-RELEASE-PURE-Z-CLEAR"' in own_source
            ),
            "safe_floor_130": "safe_floor_z = 130.0" in own_source,
            "stable_three_samples": "if len(recent) == 3:" in own_source,
            "safe_floor_log": "[FIX113-{label}-SAFE-FLOOR-ACCEPT]" in own_source,
            "fix113_module_patch_present": "def _patch_d50_module(" in own_source,
            "fix113_case2_runtime_present": "def _fix113_execute_case2(" in own_source,
        }

        shared_camera_checks = {
            "integrated_entrypoint": "def run_integrated(external_preview: Any" in own_source,
            "external_preview_factory": "class _V22ExternalPreviewFactory" in own_source,
            "fix11_args_preserved_by_shared_factory": (
                "REGISTRY.fix11_args = fix11_args" in own_source
                and "[GARMENT-TRANSFER-V9-FIX11-ARGS]" in own_source
                and 'fix11_args = args[0] if args else kwargs.get("args")' in own_source
            ),
            "no_external_stop": "[GARMENT-TRANSFER-V9-CAMERA-HANDOFF]" in own_source,
            "raw_frame_bridge_log": "[GARMENT-TRANSFER-V9-SHARED-CAMERA]" in own_source,
        }

        board_ready_ok = all(board_ready_checks.values())
        case2_safe_ok = all(case2_safe_checks.values())
        shared_camera_ok = all(shared_camera_checks.values())
        all_ok = bool(board_ready_ok and case2_safe_ok and shared_camera_ok)

        builtins.print(
            f"[GARMENT-TRANSFER-V9-SELF-TEST] inheritedFix130=True "
            f"boardReadyCut={board_ready_ok} case2SafeFloor={case2_safe_ok} "
            f"sharedCamera={shared_camera_ok} "
            f"readyPos={ready_pos} nextRecenterPos={recenter_pos}"
        )
        for name, ok in board_ready_checks.items():
            builtins.print(f"[GARMENT-TRANSFER-V9-CHECK] boardReady.{name}={bool(ok)}")
        for name, ok in case2_safe_checks.items():
            builtins.print(f"[GARMENT-TRANSFER-V9-CHECK] case2Safe.{name}={bool(ok)}")
        for name, ok in shared_camera_checks.items():
            builtins.print(f"[GARMENT-TRANSFER-V9-CHECK] sharedCamera.{name}={bool(ok)}")

        return 0 if all_ok else 2
    except Exception as exc:
        builtins.print(f"[GARMENT-TRANSFER-V8-SELF-TEST-FAIL] {exc!r}")
        return 2



def self_test() -> int:
    """Non-physical structural test using packaged internal runtime sources."""
    basket_path = (SCRIPT_DIR / INTERNAL_BASKET_RUNTIME_SOURCE).resolve()
    board_path = (SCRIPT_DIR / INTERNAL_BOARD_RUNTIME_SOURCE).resolve()
    return int(_self_test(basket_path, board_path))


def _fix78_resolve_pose_model_preflight(requested: str) -> Path:
    """Resolve the upper-garment pose engine BEFORE camera/serial/robot startup.

    Rules:
    1) exact requested path wins;
    2) if it is missing, search a few known project roots for the exact basename;
    3) only if exactly one exact-basename match exists is it auto-selected;
    4) otherwise fail early, before any RoArm motion, with candidate diagnostics.
    """
    raw = Path(str(requested)).expanduser()
    if raw.is_file():
        return raw.resolve()

    basename = raw.name
    roots = [
        Path("/workspace/project_train/aruco_test/dual/models"),
        Path("/workspace/project_train/aruco_test/dual"),
        Path("/workspace/project_train/yolo26"),
        Path("/workspace/models"),
    ]
    exact_matches = []
    seen = set()
    for root in roots:
        if not root.exists():
            continue
        try:
            for candidate in root.rglob(basename):
                if not candidate.is_file():
                    continue
                resolved = candidate.resolve()
                if str(resolved) not in seen:
                    seen.add(str(resolved))
                    exact_matches.append(resolved)
        except Exception:
            continue

    if len(exact_matches) == 1:
        chosen = exact_matches[0]
        builtins.print(
            f"[FIX81-POSE-PATH-AUTOFOUND] requested={requested} -> {chosen}"
        )
        return chosen

    # Diagnostic-only fuzzy candidates: never auto-pick among them.
    fuzzy = []
    fuzzy_seen = set()
    patterns = ("*top*pose*.engine", "*tshirt*pose*.engine")
    for root in roots:
        if not root.exists():
            continue
        for pattern in patterns:
            try:
                for candidate in root.rglob(pattern):
                    if not candidate.is_file():
                        continue
                    resolved = candidate.resolve()
                    if str(resolved) not in fuzzy_seen:
                        fuzzy_seen.add(str(resolved))
                        fuzzy.append(resolved)
                    if len(fuzzy) >= 20:
                        break
            except Exception:
                continue
            if len(fuzzy) >= 20:
                break
        if len(fuzzy) >= 20:
            break

    details = ""
    if exact_matches:
        details += " exact-basename-matches=" + " | ".join(str(x) for x in exact_matches)
    if fuzzy:
        details += " nearby-pose-engines=" + " | ".join(str(x) for x in fuzzy)
    raise MergeRuntimeError(
        "FIX81 upper-garment pose engine is missing BEFORE robot startup. "
        f"requested={requested}." + details +
        " Use --tshirt-pose-model /actual/path/to/model.engine"
    )


def main() -> int:
    builtins.print(f"[BUILD] {BUILD_ID}")
    settings, user_args = _extract_launcher_args(sys.argv[1:])
    # FIX77 authoritative mode: learning stays retired, while the upper-garment
    # pose engine is forced ON for observation-only mask+pose visualization.
    settings["training_depth_top3"] = False
    settings["training_garment_id"] = ""
    settings["tshirt_pose_overlay"] = True
    settings["tshirt_pose_model"] = str(
        settings.get("tshirt_pose_model", FIX17_TSHIRT_POSE_DEFAULT_MODEL)
        or FIX17_TSHIRT_POSE_DEFAULT_MODEL
    )
    fix11_path = (SCRIPT_DIR / INTERNAL_BASKET_RUNTIME_SOURCE).resolve()
    d50_path = (SCRIPT_DIR / INTERNAL_BOARD_RUNTIME_SOURCE).resolve()

    if bool(settings["self_test"]):
        return self_test()

    # FIX79: verify/resolve the pose engine before camera, serial, or robot startup.
    pose_preflight = _fix78_resolve_pose_model_preflight(str(settings["tshirt_pose_model"]))
    settings["tshirt_pose_model"] = str(pose_preflight)
    builtins.print(f"[FIX81-POSE-PREFLIGHT-OK] model={pose_preflight}")

    for label, path in (("basket-runtime", fix11_path), ("board-runtime", d50_path)):
        if not path.is_file():
            raise MergeRuntimeError(f"{label} source file not found: {path}")

    # Runtime imports such as step_d25_v2.py must resolve from the Jetson project
    # directory that contains this merged launcher and the two source files.
    source_dirs = [str(SCRIPT_DIR), str(fix11_path.parent), str(d50_path.parent)]
    for directory in reversed(source_dirs):
        if directory not in sys.path:
            sys.path.insert(0, directory)

    builtins.print("[GARMENT-TRANSFER-V7-WORKFLOW] ARM2 basket pickup -> FIX80 board place -> FIX113 CASE1/CASE2 recovery if needed -> mandatory fresh board confirmation -> BOARD_READY -> STOP before ARM1 91mm recenter")
    builtins.print("[MERGE-INVARIANT] one process; ELP-Raw-Preview is sole VideoCapture owner/read thread; one serial open per arm")
    builtins.print(
        f"[FIX44-GRIPPER] garment grasp stroke -30% only: OPEN={FIX44_GRASP_OPEN_ANGLE_RAD:.4f}rad "
        f"CLOSE={FIX44_GRASP_CLOSE_ANGLE_RAD:.4f}rad basketPostOpen={FIX44_BASKET_POST_CONTACT_OPEN_PERCENT:.1f}% | "
        "basket probe pre-open, release and standby angles unchanged"
    )
    builtins.print(
        f"[FIX108-BASKET-GRIP] contact-confirmed -> extraDown={FIX105_BASKET_EXTRA_DESCENT_MM:.1f}mm "
        f"-> ARM2 basketClose={FIX69_ARM2_BASKET_CLOSE_ANGLE_RAD:.4f}rad | "
        f"basket-to-center speed={FIX105_BASKET_CENTER_SPEED:.2f} (+20%) | initial basket keys=AUTO"
    )
    builtins.print(
        f"[FIX108-RECENTER-CONFIG] pull={FIX105_RECENTER_PULL_MM:.1f}mm (+30%) | "
        "direct clear->grasp approach | ARM1 preferred, ARM2 exact-board-path fallback"
    )
    builtins.print(
        f"[FIX130-GRASP-CONTACT-POLICY] ARM1 recenter Z={_FIX130_BOARD_CONTACT_Z_MM:.1f}mm | "
        f"ARM1 adaptive-correction Z={_FIX130_BOARD_CONTACT_Z_MM:.1f}mm | "
        f"first dual grasp ARM1/ARM2 Z={_FIX130_BOARD_CONTACT_Z_MM:.1f}mm | "
        f"dynamic ARM1 final extra inset={_FIX122_ARM1_FINAL_EXTRA_INSET_MM:.1f}mm "
        "(Z-only override; all other motion logic unchanged)"
    )
    builtins.print(
        f"[FIX129-BASKET-GRASP-POLICY] FIX128/FIX120 flow preserved | closeCmd={FIX69_ARM2_BASKET_CLOSE_ANGLE_RAD:.4f}rad | "
        "after existing close/feedback -> original FIX11 full lift immediately; "
        "FIX127 +15mm rise/latch/force-close gate removed; all non-basket algorithms unchanged"
    )

    d50_module = None
    try:
        # -------------------------- FIX11 PHASE --------------------------
        fix11_module = _load_source_module(
            "_merged_fix11_v8",
            fix11_path,
            transform=_patch_fix11_source,
        )
        _patch_fix11_module(fix11_module, settings, user_args)

        if _INTEGRATION_EXTERNAL_PREVIEW is not None:
            external_preview = _INTEGRATION_EXTERNAL_PREVIEW
            REGISTRY.fix11_preview = external_preview

            class _V22ExternalPreviewFactory:
                def __new__(cls, *args, **kwargs):
                    # FIX11 calls RawPreviewController(args).  The shared-camera
                    # bridge must preserve that ORIGINAL FIX11 argparse Namespace
                    # because FIX28 later reads REGISTRY.fix11_args.
                    fix11_args = args[0] if args else kwargs.get("args")
                    if fix11_args is None:
                        raise MergeRuntimeError(
                            "V22 shared-camera bridge received no FIX11 camera args"
                        )
                    with REGISTRY.lock:
                        REGISTRY.fix11_args = fix11_args
                        REGISTRY.fix11_preview = external_preview
                    builtins.print(
                        "[GARMENT-TRANSFER-V9-FIX11-ARGS] preserved FIX11 argparse "
                        "Namespace before FIX28 prewarm/baseline gate"
                    )
                    return external_preview

            # FIX11 still executes its validated basket/motion logic, but its
            # RawPreviewController constructor is replaced by the existing V22
            # camera provider. Therefore no second VideoCapture is opened.
            fix11_module.RawPreviewController = _V22ExternalPreviewFactory
            builtins.print(
                "[GARMENT-TRANSFER-V9-CAMERA-BRIDGE] FIX11 RawPreviewController "
                "redirected to V22 shared RAW-frame provider"
            )

        fix11_argv = _build_fix11_argv(user_args)
        if _integration_stop_requested():
            builtins.print("[GARMENT-TRANSFER-V10-STOP] stop before FIX11 physical phase")
            return 130
        builtins.print("\n========== MERGED PHASE 1: FIX11 BASKET FRONTEND ==========")
        builtins.print("[PHASE-1-AUTO] FINAL empty-board -> automatic B/H/Enter/D/Enter -> FIX80 ARM2 arc-place")
        with _temporary_argv(fix11_argv), _parse_known_args_context(), _fix11_completion_print_hook():
            fix11_result = fix11_module.main()
        builtins.print(f"[MERGE] FIX11 main returned: {fix11_result!r}")
        if _integration_stop_requested():
            builtins.print("[GARMENT-TRANSFER-V10-STOP] stop after FIX11; D50 phase blocked")
            return 130

        if not REGISTRY.fix11_complete:
            builtins.print(
                "[MERGE-STOP] FIX11 phase ended before successful FIX76 initial placement; "
                "D50 will not start"
            )
            return 3
        preview = REGISTRY.fix11_preview
        preview_thread = None if preview is None else getattr(preview, "_thread", None)
        preview_error = None if preview is None else getattr(preview, "_error", None)
        if (
            preview is None
            or preview_thread is None
            or not preview_thread.is_alive()
            or preview_error is not None
        ):
            raise MergeRuntimeError(
                f"persistent camera pump unavailable after FIX11: {preview_error!r}"
            )
        preview.clear_override()
        preview.set_status(
            "FIX11 COMPLETE | D50 TensorRT loading | camera remains live"
        )
        builtins.print(
            "[MERGE-CAMERA-PUMP] verified alive after FIX11; physical capture "
            "continues in ELP-Raw-Preview thread"
        )

        # --------------------------- D50 PHASE ---------------------------
        builtins.print("\n========== MERGED PHASE 2: D50 PERCEPTION / MOTION ==========")
        builtins.print("[PHASE-2] FIX11 complete; loading TensorRT models now")
        builtins.print("[PHASE-2-AUTO] transfer-integrity CASE1/CASE2 only -> mandatory fresh board confirmation -> BOARD_READY -> normal cleanup/exit; ARM1 recenter and all upper-only motion are unreachable in this executable")
        d50_module = _load_source_module(
            "_merged_d50_v14_core",
            d50_path,
            transform=_patch_d50_source_for_transfer,
        )
        terminal_reader = MergedTerminalKeyReader()
        _patch_d50_module(d50_module, user_args, terminal_reader, fix11_module, settings)
        _fix110_runtime_namespace_contract(d50_module)
        d50_argv = _build_d50_argv(user_args)
        if _integration_stop_requested():
            builtins.print("[GARMENT-TRANSFER-V10-STOP] stop before D50; D50 startup blocked")
            return 130
        with terminal_reader, _temporary_argv(d50_argv), _parse_known_args_context():
            result = int(d50_module.main())
        if _integration_stop_requested():
            builtins.print("[GARMENT-TRANSFER-V10-STOP] stop during D50; BOARD_READY/serial handoff blocked")
            return 130
        # Export only after D50 reported BOARD_READY. Until the export callback
        # returns successfully, REGISTRY remains the sole physical serial owner.
        # The UI retains this open ARM2 session through classification and must
        # explicitly close it on TOP, stop, error, or after BOTTOM finishes.
        if result == 0 and _INTEGRATION_EXTERNAL_PREVIEW is not None and callable(_INTEGRATION_ARM2_SERIAL_EXPORT):
            with REGISTRY.lock:
                arm2_port = str(getattr(REGISTRY.fix11_args, 'arm2_port', '/dev/roarm_2'))
                arm2_obj = REGISTRY.fix11_serial_by_port.get(arm2_port)
                if arm2_obj is None or not bool(getattr(getattr(arm2_obj, 'ser', None), 'is_open', False)):
                    raise MergeRuntimeError('ARM2 handoff unavailable or serial already closed; cannot continue')
                if arm2_port != '/dev/roarm_2':
                    raise MergeRuntimeError(f'ARM2 handoff port mismatch: {arm2_port}')
                # Callback is a pure ownership transfer (NO serial write/read).
                _INTEGRATION_ARM2_SERIAL_EXPORT(arm2_port, arm2_obj.ser)
                REGISTRY.fix11_serial_by_port.pop(arm2_port, None)
                builtins.print(f'[TRANSFER-ARM2-HANDOFF] exact existing open serial exported port={arm2_port}; no close/reopen')
        return result
    finally:
        # FIX76: no Dataset V2/session/ZIP finalization exists.
        # Stop the camera in the same ELP-Raw-Preview thread that opened and
        # continuously read the physical VideoCapture.
        preview = REGISTRY.fix11_preview
        if preview is not None:
            if _INTEGRATION_EXTERNAL_PREVIEW is not None:
                builtins.print(
                    "[GARMENT-TRANSFER-V9-CAMERA-HANDOFF] transfer finished; "
                    "V22 camera remains OPEN/LIVE"
                )
            else:
                try:
                    preview.stop(timeout=3.0)
                except Exception as exc:
                    builtins.print(f"[MERGE-CAMERA-PUMP-WARN] stop failed: {exc!r}")
        _close_physical_serials()


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except KeyboardInterrupt:
        builtins.print(
            "\n[MERGE-CTRL+C] operator abort received; camera pump, terminal, "
            "and shared serial cleanup completed"
        )
        raise SystemExit(130)
